// 库存明细详情页-库存修正
const containerId = ctx.ev.leafContainer

let lines = []

// 将符合条件的库存明细加载到页面上
let c = []
if (!!containerId && containerId.trim().length > 0) {
  c.push(__jk.cqEq("leafContainer", containerId.trim()))
}
if (c.length <= 0) {
  // console.log("没指定容器和库位，清空单行")
  lines = null
} else {
  console.log("c=", c)
  const r = await __jk.getHttpClient().post("entity/find/many", {entityName: "FbInvLayout", query: __jk.cqOr(c)})
  console.table(r.data)
  lines = r.data
  if (!!lines) {
    lines.forEach((e, idx) => {
      e["refInvId"] = e["id"]
      e["id"] = null
    })
  }
}

ctx.close()
__jk.toEntityCreatePage("NsInvAdjustOrder", {container: containerId, btBzKind: "AdjustByContainer", btLines: lines})
